 <section id="services" class="brand-section container"><div class="brand-section-title service-section-heading"><div><span>خدمات {{platform.name}}</span><h2>از نیاز شما، تا مسیر مراقبت</h2></div><p>{{detail.serviceIntro}}</p></div><div class="brand-service-list"><article v-for="(service,i) in platform.services" :key="service" class="brand-service-card"><div class="service-card-heading"><span class="service-icon"><PlatformIcon :name="['activity','heart','flower','leaf'][i%4]" :size="25"/></span><h3>{{service}}</h3></div><p>{{story.services[i][0]}}</p><span class="service-outcome">{{detail.serviceNotes[i]||detail.serviceNotes[0]}}</span><a href="#booking" @click="chooseDoctor(doctors[i%doctors.length]?.id||'')">انتخاب متخصص و زمان<ArrowLeft :size="17"/></a></article></div></section>
